// test-migrations-clean.js
// Script para testar migrations em banco limpo

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

console.log('='.repeat(80));
console.log('🧪 TESTE DE MIGRATIONS EM BANCO LIMPO');
console.log('='.repeat(80));
console.log('');

// Verificar se .env existe
const envPath = path.join(__dirname, '.env');
if (!fs.existsSync(envPath)) {
  console.error('❌ Arquivo .env não encontrado!');
  console.error('   Crie um arquivo .env com as configurações do banco de dados.');
  process.exit(1);
}

// Ler .env para mostrar qual banco será usado
const envContent = fs.readFileSync(envPath, 'utf-8');
const dbMatch = envContent.match(/DATABASE_URL=(.+)/);
const dbName = dbMatch ? dbMatch[1].split('/').pop() : 'N/A';

console.log(`📊 Banco de dados: ${dbName}`);
console.log('');

// Listar migrations que serão executadas
const migrationsDir = path.join(__dirname, 'migrations');
const migrationFiles = fs.readdirSync(migrationsDir)
  .filter(f => f.endsWith('.sql'))
  .sort();

console.log(`📋 Total de migrations encontradas: ${migrationFiles.length}`);
console.log('');
console.log('Ordem de execução:');
migrationFiles.forEach((file, index) => {
  console.log(`  ${(index + 1).toString().padStart(2, '0')}. ${file}`);
});
console.log('');

// Executar migrations
console.log('🚀 Iniciando execução das migrations...');
console.log('');

try {
  const output = execSync('npm run migrate', {
    encoding: 'utf-8',
    stdio: 'pipe',
    cwd: __dirname
  });

  console.log(output);
  console.log('');
  console.log('✅ Todas as migrations foram executadas com sucesso!');
  console.log('');

  // Verificar tabelas criadas
  console.log('📊 Verificando tabelas criadas...');
  console.log('');
  
  // Lista de tabelas esperadas (principais)
  const expectedTables = [
    'tenants',
    'users',
    'roles',
    'permissions',
    'jobs',
    'assignments',
    'accounts',
    'transactions',
    'groups',
    'posts',
    'global_users'
  ];

  console.log('Tabelas esperadas (verificação manual necessária):');
  expectedTables.forEach(table => {
    console.log(`  - ${table}`);
  });
  console.log('');
  console.log('💡 Execute manualmente: SELECT table_name FROM information_schema.tables WHERE table_schema = \'public\';');
  console.log('');

} catch (error) {
  console.error('❌ Erro ao executar migrations:');
  console.error(error.stdout || error.message);
  console.error('');
  console.error('Detalhes do erro:');
  console.error(error.stderr || error);
  process.exit(1);
}

console.log('='.repeat(80));
console.log('✨ TESTE DE MIGRATIONS CONCLUÍDO');
console.log('='.repeat(80));
















